/**
 * Repoints every issue carrying `sourceLabelId` onto `targetLabelId`, then
 * removes the source label. Issues that already carry both collapse onto a
 * single row via `onConflictDoNothing`, and archived issues are included
 * since the join table carries no archive state of its own.
 *
 * Returns the number of issues that carried the source label.
 */
export async function mergeLabels(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  const db = getDb();

  const carriers = db
    .select({ issueId: issueLabels.issueId })
    .from(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.labelId, sourceLabelId),
      ),
    )
    .all();

  db.delete(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.labelId, sourceLabelId),
      ),
    )
    .run();

  if (carriers.length > 0) {
    db.insert(issueLabels)
      .values(
        carriers.map(({ issueId }) => ({
          orgId,
          issueId,
          labelId: targetLabelId,
        })),
      )
      .onConflictDoNothing()
      .run();
  }

  db.delete(labels)
    .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
    .run();

  return carriers.length;
}

