import { afterAll, beforeAll, describe, expect, it } from "vitest";

import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { NotFoundError } from "@/server/services/_support";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as labelService from "@/server/services/label-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
let otherTenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("mergelbl");
  otherTenant = await createTenant("mergelbl2");
});

afterAll(() => {
  cleanup();
});

describe("scratch merge labels", () => {
  it("rejects cross-tenant orgId", async () => {
    const bug = await labelRepo.insertLabel({ orgId: tenant.org.id, name: "bug", color: "#ff0000", description: null });
    const defect = await labelRepo.insertLabel({ orgId: tenant.org.id, name: "defect", color: "#00ff00", description: null });
    await expect(
      labelService.mergeLabels(otherTenant.actors.owner, {
        orgId: tenant.org.id,
        sourceLabelId: defect.id,
        targetLabelId: bug.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("rejects without project:archive permission", async () => {
    const bug = await labelRepo.insertLabel({ orgId: tenant.org.id, name: "bug2", color: "#ff0000", description: null });
    const defect = await labelRepo.insertLabel({ orgId: tenant.org.id, name: "defect2", color: "#00ff00", description: null });
    await expect(
      labelService.mergeLabels(tenant.actors.member, {
        orgId: tenant.org.id,
        sourceLabelId: defect.id,
        targetLabelId: bug.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("rejects when source label missing/foreign, changes nothing", async () => {
    const bug = await labelRepo.insertLabel({ orgId: tenant.org.id, name: "bug3", color: "#ff0000", description: null });
    const foreign = await labelRepo.insertLabel({ orgId: otherTenant.org.id, name: "foreign", color: "#00ff00", description: null });
    await expect(
      labelService.mergeLabels(tenant.actors.admin, {
        orgId: tenant.org.id,
        sourceLabelId: foreign.id,
        targetLabelId: bug.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    const stillThere = await labelRepo.findLabelById(otherTenant.org.id, foreign.id);
    expect(stillThere).not.toBeNull();
  });

  it("rejects self-merge even bypassing schema, changes nothing", async () => {
    const same = await labelRepo.insertLabel({ orgId: tenant.org.id, name: "same", color: "#ff0000", description: null });
    await expect(
      labelService.mergeLabels(tenant.actors.admin, {
        orgId: tenant.org.id,
        sourceLabelId: same.id,
        targetLabelId: same.id,
      }),
    ).rejects.toThrow();
    const stillThere = await labelRepo.findLabelById(tenant.org.id, same.id);
    expect(stillThere).not.toBeNull();
  });

  it("merges: relabels issues (including archived), dedupes, deletes source, counts correctly", async () => {
    const bug = await labelRepo.insertLabel({ orgId: tenant.org.id, name: "bug4", color: "#ff0000", description: null });
    const defect = await labelRepo.insertLabel({ orgId: tenant.org.id, name: "defect4", color: "#00ff00", description: null });

    const issueOnlySource = await issueRepo.insertIssue(issueInput(tenant.org.id, tenant.project.id, { title: "only source" }), tenant.userIds.owner, 9001);
    const issueBoth = await issueRepo.insertIssue(issueInput(tenant.org.id, tenant.project.id, { title: "both" }), tenant.userIds.owner, 9002);
    const issueNeither = await issueRepo.insertIssue(issueInput(tenant.org.id, tenant.project.id, { title: "neither" }), tenant.userIds.owner, 9003);
    const issueArchived = await issueRepo.insertIssue(issueInput(tenant.org.id, tenant.project.id, { title: "archived+source" }), tenant.userIds.owner, 9004);

    await labelRepo.setIssueLabels(tenant.org.id, issueOnlySource.id, [defect.id]);
    await labelRepo.setIssueLabels(tenant.org.id, issueBoth.id, [defect.id, bug.id]);
    await labelRepo.setIssueLabels(tenant.org.id, issueArchived.id, [defect.id]);
    await issueRepo.archiveIssue(tenant.org.id, issueArchived.id);

    const result = await labelService.mergeLabels(tenant.actors.admin, {
      orgId: tenant.org.id,
      sourceLabelId: defect.id,
      targetLabelId: bug.id,
    });

    expect(result.issuesRelabelled).toBe(3);
    expect(result.label.id).toBe(bug.id);

    const gone = await labelRepo.findLabelById(tenant.org.id, defect.id);
    expect(gone).toBeNull();

    const labelsByIssue = await labelRepo.listLabelsForIssues(tenant.org.id, [
      issueOnlySource.id,
      issueBoth.id,
      issueNeither.id,
      issueArchived.id,
    ]);

    expect((labelsByIssue[issueOnlySource.id] ?? []).map((l) => l.id)).toEqual([bug.id]);
    expect((labelsByIssue[issueBoth.id] ?? []).map((l) => l.id)).toEqual([bug.id]);
    expect(labelsByIssue[issueNeither.id] ?? []).toEqual([]);
    expect((labelsByIssue[issueArchived.id] ?? []).map((l) => l.id)).toEqual([bug.id]);
  });
});

